    require(_newOracle != crvusdToUSDOracle, "Same oracle");

    address oldOracle = crvusdToUSDOracle;
    crvusdToUSDOracle = _newOracle;

    emit CrvUSDOracleUpdated(oldOracle, _newOracle);
}

