        uint256 total = 0;
        // buy 10 batches of wearables
        for (uint256 i; i < 10; i++) {
            uint256 amount = 1e18 + 49_999;
            total += amount;
            uint256 buyPrice = sofa.getBuyPriceAfterFee(wearablesSubject, amount);
            sofa.buyWearables{value: buyPrice}(wearablesSubject, amount);
